package android.os; import java.util.ArrayDeque; public class Handler { static final ArrayDeque<Runnable> tasks=new ArrayDeque<>(); public Handler(Object looper) {} public boolean postAtTime(Runnable r,Object token,long time){tasks.add(r);return true;} public void removeCallbacks(Runnable r){tasks.removeIf(t -> t==r);} public void removeCallbacksAndMessages(Object token){tasks.clear();} public static void runOne(){Runnable task=tasks.poll();if(task!=null)task.run();} }
